# ===================================================================
# 1. displot(kind="hist", kde=True) — KDE overlay via named transforms
# ===================================================================


class TestDisplotKdeOverlay:
    """Tests for the refactored KDE overlay path in distribution.py lines 282-318.
    The overlay uses named-transform routing to avoid Bin contamination."""

    def test_hist_kde_overlay_renders_valid_svg(self, iris_like):
        """displot(kde=True) should render SVG without NaN or Infinity.
        Exercises distribution.py lines 303-318: _KdeTransform with name='kde_overlay'."""
        chart = fm.displot(iris_like, x="sepal_length", kde=True)
        svg = chart.to_svg()
        assert "<svg" in svg
        assert "NaN" not in svg
        assert "Infinity" not in svg

    def test_hist_kde_overlay_has_two_layers(self, iris_like):
        """The layered chart should have at least 2 layers (histogram + kde).
        distribution.py lines 293-300: primary layer promoted, then kde appended."""
        chart = fm.displot(iris_like, x="sepal_length", kde=True)
        spec = json.loads(chart.to_spec().to_json())
        layers = spec.get("layers", [])
        assert len(layers) >= 2, f"Expected >=2 layers, got {len(layers)}"
        # One layer should be the kde overlay with data_source
        kde_layers = [l for l in layers if l.get("data_source") == "kde_overlay"]
        assert len(kde_layers) == 1, "Expected exactly 1 kde overlay layer"

    def test_hist_kde_overlay_has_named_kde_transform(self, iris_like):
        """The chart should include a named Kde transform with name='kde_overlay'.
        distribution.py line 307: Kde(..., name='kde_overlay')."""
        chart = fm.displot(iris_like, x="sepal_length", kde=True)
        spec = json.loads(chart.to_spec().to_json())
        transforms = spec.get("transforms", [])
        kde_xforms = [t for t in transforms if t.get("type") == "kde"]
        assert len(kde_xforms) >= 1, "No Kde transform found in spec"
        named_kde = [t for t in kde_xforms if t.get("name") == "kde_overlay"]
        assert len(named_kde) == 1, "Expected named 'kde_overlay' transform"

    def test_hist_kde_overlay_kde_reads_original_field(self, iris_like):
        """The kde_overlay layer encoding should map x='value', y='density'.
        distribution.py lines 314-318: encoding={x: 'value', y: 'density'}."""
        chart = fm.displot(iris_like, x="sepal_length", kde=True)
        spec = json.loads(chart.to_spec().to_json())
        layers = spec.get("layers", [])
        kde_layer = next((l for l in layers if l.get("data_source") == "kde_overlay"), None)
        assert kde_layer is not None
        enc = kde_layer.get("encoding", {})
        assert enc.get("x", {}).get("field") == "value" or enc.get("x") == "value"
        assert enc.get("y", {}).get("field") == "density" or enc.get("y") == "density"


