class TestDisplotKdeOnlyPath:
    """Regression tests for the original kind='kde' path (distribution.py lines 233-247).
    Ensure the named-transform refactor didn't break the primary kde path."""

    def test_kde_only_renders(self, iris_like):
        """displot(kind='kde') should still work after the overlay refactor."""
        chart = fm.displot(iris_like, x="sepal_length", kind="kde")
        svg = chart.to_svg()
        assert "<svg" in svg
        assert "NaN" not in svg

    def test_kde_only_with_hue(self, iris_like):
        """displot(kind='kde', hue=...) should produce per-group KDE curves."""
        chart = fm.displot(iris_like, x="sepal_length", hue="species", kind="kde")
        svg = chart.to_svg()
        assert "<svg" in svg
        assert "NaN" not in svg

    def test_kde_only_with_fill_false(self, iris_like):
        """displot(kind='kde', fill=False) should produce unfilled KDE lines."""
        chart = fm.displot(iris_like, x="sepal_length", kind="kde", fill=False)
        svg = chart.to_svg()
        assert "<svg" in svg

    def test_kde_only_does_not_have_overlay_transforms(self, iris_like):
        """kind='kde' should NOT have 'kde_overlay' or 'rug_data' named transforms.
        The overlay refactor should not touch the primary kde path."""
        chart = fm.displot(iris_like, x="sepal_length", kind="kde")
        spec = json.loads(chart.to_spec().to_json())
        transforms = spec.get("transforms", [])
        names = [t.get("name") for t in transforms if t.get("name")]
        assert "kde_overlay" not in names
        assert "rug_data" not in names

    def test_kde_kind_with_kde_true_no_double_kde(self, iris_like):
        """displot(kind='kde', kde=True) — kde=True is a no-op when kind is already 'kde'.
        distribution.py line 303: 'if kde and kind != "kde"'."""
        chart = fm.displot(iris_like, x="sepal_length", kind="kde", kde=True)
        spec = json.loads(chart.to_spec().to_json())
        # Should not have a separate kde_overlay — the primary IS the kde
        transforms = spec.get("transforms", [])
        named = [t.get("name") for t in transforms if t.get("name")]
        assert "kde_overlay" not in named

    def test_rug_kind_with_rug_true_no_double_rug(self, iris_like):
        """displot(kind='rug', rug=True) — rug=True is a no-op when kind is 'rug'.
        distribution.py line 321: 'if rug and kind != "rug"'."""
        chart = fm.displot(iris_like, x="sepal_length", kind="rug", rug=True)
        spec = json.loads(chart.to_spec().to_json())
        transforms = spec.get("transforms", [])
        named = [t.get("name") for t in transforms if t.get("name")]
        assert "rug_data" not in named


# ===================================================================
# 5. residplot(label=...) — label column survives Smooth transform
# ===================================================================


class TestResidplotLabel:
    """Tests for residplot label parameter with groupby='_label' on Smooth.
    Targets regression.py lines 828-851."""

    def test_residplot_label_renders_svg(self, simple_float_df):
        """residplot(label='MyLabel') should produce valid SVG.
        regression.py line 849-851: Smooth(groupby='_label')."""
        chart = fm.residplot(
            simple_float_df,
            x="x",
            y="y",
            label="MyLabel",
            show_metrics=False,
            zero_line=False,
        )
        svg = chart.to_svg()
        assert "<svg" in svg
        assert "NaN" not in svg

    def test_residplot_label_injects_label_column(self, simple_float_df):
        """The data should have a '_label' column after injection.
        regression.py line 831: data.with_columns(pl.lit(str(label)).alias('_label'))."""
        chart = fm.residplot(
            simple_float_df,
            x="x",
            y="y",
            label="series A",
            show_metrics=False,
            zero_line=False,
        )
        # Check the chart's internal data has the _label column
        assert "_label" in chart._data.columns

    def test_residplot_label_sets_color_encoding(self, simple_float_df):
        """residplot(label=...) should map color='_label' in encoding.
        regression.py line 855: enc['color'] = '_label'."""
        chart = fm.residplot(
            simple_float_df,
            x="x",
            y="y",
            label="Residuals",
            show_metrics=False,
            zero_line=False,
        )
        spec = json.loads(chart.to_spec().to_json())
        # The encoding should have color mapped to _label
        enc = spec.get("encoding", {})
        color_field = enc.get("color", {}).get("field", enc.get("color"))
        assert color_field == "_label"

    def test_residplot_label_smooth_has_groupby(self, simple_float_df):
        """The Smooth transform should have groupby='_label'.
        regression.py line 850: smooth_kwargs['groupby'] = '_label'."""
        chart = fm.residplot(
            simple_float_df,
            x="x",
            y="y",
            label="test",
            show_metrics=False,
            zero_line=False,
        )
        spec = json.loads(chart.to_spec().to_json())
        smooth_t = next(
            (t for t in spec.get("transforms", []) if t.get("type") == "smooth"),
            None,
        )
        assert smooth_t is not None, "No smooth transform found"
        assert smooth_t.get("groupby") == ["_label"]

    def test_residplot_label_with_show_metrics(self, simple_float_df):
        """residplot(label=..., show_metrics=True) should render with metrics annotation.
        Both label column preservation and metrics injection."""
        chart = fm.residplot(
            simple_float_df,
            x="x",
            y="y",
            label="series",
            show_metrics=True,
            zero_line=True,
        )
        svg = chart.to_svg()
        assert "<svg" in svg
        assert "NaN" not in svg

    def test_residplot_label_with_lowess(self, simple_float_df):
        """residplot(label=..., lowess=True) — label + lowess smoother overlay.
        regression.py lines 891-908: lowess layer added alongside label."""
        chart = fm.residplot(
            simple_float_df,
            x="x",
            y="y",
            label="data",
            lowess=True,
            show_metrics=False,
            zero_line=False,
        )
        svg = chart.to_svg()
        assert "<svg" in svg
        assert "NaN" not in svg

    def test_residplot_label_color_parameter_overrides(self, simple_float_df):
        """residplot(label=..., color=...) — explicit color overrides _label.
        regression.py lines 855-858: color wins over label."""
        chart = fm.residplot(
            simple_float_df,
            x="x",
            y="y",
            label="test",
            color="x",
            show_metrics=False,
            zero_line=False,
        )
        spec = json.loads(chart.to_spec().to_json())
        enc = spec.get("encoding", {})
        color_field = enc.get("color", {}).get("field", enc.get("color"))
        assert color_field == "x", "Explicit color= should override label"

    def test_residplot_robust_no_label_support(
        self, simple_float_df
    ):  # BUG: ValueError: unknown column '_label' — Robust transform drops _label column but encoding still references it via color='_label'
        """residplot(robust=True, label=...) — Robust has no groupby, so _label
        is dropped by the transform output, but the encoding still references
        it via color='_label', causing a ValueError at render time.
        regression.py line 826-827 warns about the limitation but doesn't guard against it."""
        chart = fm.residplot(
            simple_float_df,
            x="x",
            y="y",
            label="robust_label",
            robust=True,
            show_metrics=False,
            zero_line=False,
        )
        svg = chart.to_svg()
        assert "<svg" in svg
        # The Robust transform drops _label. The encoding
        # references _label via color, causing the crash.


