class TestDisplotLayerNaming:
    """Tests that layer naming in distribution.py lines 337-359 works correctly
    after the overlay refactor."""

    def test_overlay_layers_have_names_internal(self, iris_like):
        """All internal _Layer objects in a kde=True chart should have names.
        distribution.py lines 337-359: _kind_names mapping."""
        chart = fm.displot(iris_like, x="sepal_length", kde=True)
        assert chart._layers is not None
        for i, layer in enumerate(chart._layers):
            assert layer.name is not None, f"Internal layer {i} has no name"

    def test_overlay_layers_have_distinct_names_internal(self, iris_like):
        """All internal layers should have distinct names for override targeting."""
        chart = fm.displot(iris_like, x="sepal_length", kde=True, rug=True)
        assert chart._layers is not None
        names = [l.name for l in chart._layers]
        assert len(names) == len(set(names)), f"Duplicate layer names: {names}"

    def test_layer_names_survive_json_serialization(
        self, iris_like
    ):  # BUG: layer names are silently dropped during JSON serialization — _build_layers_list omits the 'name' field
        """Layer names should be preserved in the JSON spec for round-trip fidelity.
        _build_layers_list in chart.py line 5058-5083 does not serialize layer.name."""
        chart = fm.displot(iris_like, x="sepal_length", kde=True)
        spec = json.loads(chart.to_spec().to_json())
        layers = spec.get("layers", [])
        for i, layer in enumerate(layers):
            assert layer.get("name") is not None, f"Layer {i} name dropped in JSON"


