class TestOverlaySpecRoundTrip:
    """Tests that overlay spec serialization preserves data_source fields."""

    def test_kde_overlay_data_source_in_internal_layers(self, iris_like):
        """The kde overlay internal _Layer should have data_source='kde_overlay'."""
        chart = fm.displot(iris_like, x="sepal_length", kde=True)
        assert chart._layers is not None
        kde_layer = next((l for l in chart._layers if l.name == "kde"), None)
        assert kde_layer is not None, "No internal layer named 'kde'"
        assert kde_layer.data_source == "kde_overlay"

    def test_rug_overlay_data_source_in_internal_layers(self, iris_like):
        """The rug overlay internal _Layer should have data_source='rug_data'."""
        chart = fm.displot(iris_like, x="sepal_length", rug=True)
        assert chart._layers is not None
        rug_layer = next((l for l in chart._layers if l.name == "rug"), None)
        assert rug_layer is not None, "No internal layer named 'rug'"
        assert rug_layer.data_source == "rug_data"

    def test_kde_overlay_data_source_survives_json(self, iris_like):
        """data_source should be serialized in JSON spec (unlike name which is dropped)."""
        chart = fm.displot(iris_like, x="sepal_length", kde=True)
        j = chart.to_json()
        d = json.loads(j)
        layers = d.get("layers", [])
        # data_source IS serialized by _build_layers_list (line 5068-5069)
        ds_layers = [l for l in layers if l.get("data_source") == "kde_overlay"]
        assert len(ds_layers) == 1, "No layer with data_source='kde_overlay' in spec JSON"

    def test_rug_overlay_data_source_survives_json(self, iris_like):
        """data_source should be serialized in JSON spec for rug overlay."""
        chart = fm.displot(iris_like, x="sepal_length", rug=True)
        j = chart.to_json()
        d = json.loads(j)
        layers = d.get("layers", [])
        ds_layers = [l for l in layers if l.get("data_source") == "rug_data"]
        assert len(ds_layers) == 1, "No layer with data_source='rug_data' in spec JSON"


